// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum) public {
        blockNum = bound(blockNum, 100, 1000000);
        vm.roll(blockNum);
        vm.warp(1);
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "call failed");

        bool balanceZero = address(c).balance == 0;
        bool blockDivisibleBy15 = (blockNum % 15 == 0);
        assertTrue(balanceZero == blockDivisibleBy15);
    }
}
